window.AUTH=window.AUTH||{};window.AUTH["17-1307"]={"d":"17-1307","id":"2018/17-1307","n":"Obduskey v. McCarthy & Holthus LLP","briefs":[{"k":"petitioner","label":"Brief of petitioner Dennis Obduskey","date":"2018-09-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1307/63228/20180910220120173_17-1307%20ts.pdf","side":"pet","n":42},{"k":"respondent","label":"Brief of respondent McCarthy & Holthus LLP","date":"2018-11-07","url":"https://www.supremecourt.gov/DocketPDF/17/17-1307/71286/20181107142007284_Obduskey%20brief%20for%20respondent.pdf","side":"res","n":96},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-11-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-1307/72054/20181114152356604_17-1307bsacUnitedStates.pdf","side":"us","n":51},{"k":"reply","label":"Reply of petitioner Dennis Obduskey","date":"2018-12-07","url":"https://www.supremecourt.gov/DocketPDF/17/17-1307/74576/20181207213612540_17-1307%20rb.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1307_7lho.pdf","tr":true,"items":[{"t":"case","label":"Alaska Trustee, LLC v. Ambridge","cite":"372 P.3d 207","y":2016,"court":"Alaska","url":"https://www.courtlistener.com/c/P.3d/372/207/","op":3,"by":{"0":"passim","3":"1, 8"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Cohen v. Rosicki & Assocs., P.C.","cite":"897 F.3d 75","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/897/75/","by":{"0":"21","2":"25","3":"16"}},{"t":"case","label":"Glazer v. Chase Home Fin. LLC","cite":"704 F.3d 453","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/704/453/","op":3,"by":{"0":"passim","1":"10"}},{"t":"case","label":"Heintz v. Jenkins","cite":"514 U.S. 291","y":1995,"id":"1994/94-367","sc":1,"op":1,"sum":"Observing that the FDCPA’s protections may contain certain “implici[t] exception[s]”.","sumSrc":"opinion","by":{"0":"2, 4, 20, 27","1":"32, 33","2":"11, 18, 19","3":"8, 15, 21"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"ar":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"27","1":"3, 38, 48"}},{"t":"case","label":"Ho v. ReconTrust Co., NA","cite":"858 F.3d 568","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/858/568/","op":1,"sum":"Holding that an entity whose only role is the enforcement of security interests is not a debt collector under the Act.","sumSrc":"opinion","by":{"0":"passim","1":"10, 43, 44, 48","2":"22, 23, 25, 32","3":"9, 15"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich LPA","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"0":"4, 14","1":"39, 40"}},{"t":"case","label":"Kaltenbach v. Richards","cite":"464 F.3d 524","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/464/524/","sum":"Explaining how a contrary reading would leave Section 1692i(a)(1) “without effect”.","sumSrc":"brief:0","by":{"0":"9, 21","2":"32"}},{"t":"case","label":"Kaymark v. Bank of Am., N.A.","cite":"783 F.3d 168","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/783/168/","op":1,"sum":"Holding that such an entity is a debt collector for the purpose of all the Act’s requirements.","sumSrc":"opinion","by":{"0":"23","3":"14"}},{"t":"case","label":"Lapan v. Greenspoon Marder P.A.","cite":"2018 WL 1033224","y":2018,"court":"D. Vt. Feb. 22","by":{"0":"17"}},{"t":"case","label":"McCray v. Fed. Home Loan Mortg. Corp.","cite":"839 F.3d 354","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/354/","by":{"0":"18","3":"6"}},{"t":"case","label":"McLaughlin v. Phelan Hallinan & Schmieg, LLP","cite":"756 F.3d 240","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/756/240/","by":{"0":"18","3":"7"}},{"t":"case","label":"Piper v. Portnoff Law Assocs., Ltd.","cite":"396 F.3d 227","y":2005,"court":"3d. Cir.","url":"https://www.courtlistener.com/c/F.3d/396/227/","op":1,"by":{"0":"passim","2":"25","3":"10"}},{"t":"case","label":"Reese v. Ellis, Painter, Ratterree & Adams, LLP","cite":"678 F.3d 1211","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/678/1211/","by":{"0":"22","1":"28","2":"25"}},{"t":"case","label":"Romea v. Heiberger & Assocs.","cite":"163 F.3d 111","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/163/111/","by":{"0":"16","3":"4"}},{"t":"case","label":"Shapiro & Meinhold v. Zartman","cite":"823 P.2d 120","y":1992,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/823/120/","by":{"0":"passim"}},{"t":"case","label":"Wilson v. Draper & Goldberg, P.L.L.C.","cite":"443 F.3d 373","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/373/","op":1,"by":{"0":"9","1":"28"}},{"t":"usc","label":"15 U.S.C. § 1692-1692p","url":"https://www.law.cornell.edu/uscode/text/15/1692-1692p","tname":"Commerce and Trade","by":{"0":"2","1":"passim","3":"passim"}},{"t":"usc","label":"15 U.S.C. § 1692","url":"https://www.law.cornell.edu/uscode/text/15/1692","subs":["(a)","(b)","(e)","(c)"],"stext":{"head":"§1692. Congressional findings and declaration of purpose","paras":[[0,"(a) Abusive practices"],[0,"There is abundant evidence of the use of abusive, deceptive, and unfair debt collection practices by many debt collectors. Abusive debt collection practices contribute to the number of personal bankruptcies, to marital instability, to the loss of jobs, and to invasions of individual privacy."],[0,"(b) Inadequacy of laws"],[0,"Existing laws and procedures for redressing these injuries are inadequate to protect consumers."],[0,"(c) Available non-abusive collection methods"],[0,"Means other than misrepresentation or other abusive debt collection practices are available for the effective collection of debts."],[0,"(d) Interstate commerce"],[0,"Abusive debt collection practices are carried on to a substantial extent in interstate commerce and through means and instrumentalities of such commerce. Even where abusive debt collection practices are purely intrastate in character, they nevertheless directly affect interstate commerce."],[0,"(e) Purposes"],[0,"It is the purpose of this subchapter to eliminate abusive debt collection practices by debt collectors, to insure that those debt collectors who refrain from using abusive debt collection practices are not competitively disadvantaged, and to promote consistent State action to protect consumers against debt collection abuses."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1692. Congressional findings and declaration of purpose","tname":"Commerce and Trade","by":{"0":"3, 3, 3","1":"3","2":"1, 3, 3, 3, 3","3":"4"}},{"t":"usc","label":"15 U.S.C. § 1692a","url":"https://www.law.cornell.edu/uscode/text/15/1692a","subs":["(2)","(5)","(6)","(6)(A)","(6)(C)","(6)(F)","(6)(D)","(6)(F)(iii)"],"stext":{"head":"§1692a. Definitions","paras":[[0,"As used in this subchapter—"],[1,"(1) The term \"Bureau\" means the Bureau of Consumer Financial Protection."],[1,"(2) The term \"communication\" means the conveying of information regarding a debt directly or indirectly to any person through any medium."],[1,"(3) The term \"consumer\" means any natural person obligated or allegedly obligated to pay any debt."],[1,"(4) The term \"creditor\" means any person who offers or extends credit creating a debt or to whom a debt is owed, but such term does not include any person to the extent that he receives an assignment or transfer of a debt in default solely for the purpose of facilitating collection of such debt for another."],[1,"(5) The term \"debt\" means any obligation or alleged obligation of a consumer to pay money arising out of a transaction in which the money, property, insurance, or services which are the subject of the transaction are primarily for personal, family, or household purposes, whether or not such obligation has been reduced to judgment."],[1,"(6) The term \"debt collector\" means any person who uses any instrumentality of interstate commerce or the mails in any business the principal purpose of which is the collection of any debts, or who regularly collects or attempts to collect, directly or indirectly, debts owed or due or asserted to be owed or due another. Notwithstanding the exclusion provided by clause (F) of the last sentence of this paragraph, the term includes any creditor who, in the process of collecting his own debts, uses any name other than his own which would indicate that a third person is collecting or attempting to collect such debts. For the purpose of section 1692f(6) of this title, such term also includes any person who uses any instrumentality of interstate commerce or the mails in any business the principal purpose of which is the enforcement of security interests. The term does not include—"],[2,"(A) any officer or employee of a creditor while, in the name of the creditor, collecting debts for such creditor;"],[2,"(B) any person while acting as a debt collector for another person, both of whom are related by common ownership or affiliated by corporate control, if the person acting as a debt collector does so only for persons to whom it is so related or affiliated and if the principal business of such person is not the collection of debts;"],[2,"(C) any officer or employee of the United States or any State to the extent that collecting or attempting to collect any debt is in the performance of his official duties;"],[2,"(D) any person while serving or attempting to serve legal process on any other person in connection with the judicial enforcement of any debt;"],[2,"(E) any nonprofit organization which, at the request of consumers, performs bona fide consumer credit counseling and assists consumers in the liquidation of their debts by receiving payments from such consumers and distributing such amounts to creditors; and"],[2,"(F) any person collecting or attempting to collect any debt owed or due or asserted to be owed or due another to the extent such activity (i) is incidental to a bona fide fiduciary obligation or a bona fide escrow arrangement; (ii) concerns a debt which was originated by such person; (iii) concerns a debt which was not in default at the time it was obtained by such person; or (iv) concerns a debt obtained by such person as a secured party in a commercial credit transaction involving the creditor."],[1,"(7) The term \"location information\" means a consumer's place of abode and his telephone number at such place, or his place of employment."],[1,"(8) The term \"State\" means any State, territory, or possession of the United States, the District of Columbia, the Commonwealth of Puerto Rico, or any political subdivision of any of the foregoing."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1692a. Definitions","tname":"Commerce and Trade","by":{"0":"20, 4, passim, 5, 17, 8","1":"3, 16, 34, passim, 47, 9, 48","2":"3, 3, 3","3":"7, 9, 13, passim, 4"}},{"t":"usc","label":"15 U.S.C. § 1692c","url":"https://www.law.cornell.edu/uscode/text/15/1692c","subs":["(d)","(a)","(a)(2)","(b)","(c)"],"stext":{"head":"§1692c. Communication in connection with debt collection","paras":[[0,"(a) Communication with the consumer generally"],[0,"Without the prior consent of the consumer given directly to the debt collector or the express permission of a court of competent jurisdiction, a debt collector may not communicate with a consumer in connection with the collection of any debt—"],[1,"(1) at any unusual time or place or a time or place known or which should be known to be inconvenient to the consumer. In the absence of knowledge of circumstances to the contrary, a debt collector shall assume that the convenient time for communicating with a consumer is after 8 o'clock antemeridian and before 9 o'clock postmeridian, local time at the consumer's location;"],[1,"(2) if the debt collector knows the consumer is represented by an attorney with respect to such debt and has knowledge of, or can readily ascertain, such attorney's name and address, unless the attorney fails to respond within a reasonable period of time to a communication from the debt collector or unless the attorney consents to direct communication with the consumer; or"],[1,"(3) at the consumer's place of employment if the debt collector knows or has reason to know that the consumer's employer prohibits the consumer from receiving such communication."],[0,"(b) Communication with third parties"],[0,"Except as provided in section 1692b of this title, without the prior consent of the consumer given directly to the debt collector, or the express permission of a court of competent jurisdiction, or as reasonably necessary to effectuate a postjudgment judicial remedy, a debt collector may not communicate, in connection with the collection of any debt, with any person other than the consumer, his attorney, a consumer reporting agency if otherwise permitted by law, the creditor, the attorney of the creditor, or the attorney of the debt collector."],[0,"(c) Ceasing communication"],[0,"If a consumer notifies a debt collector in writing that the consumer refuses to pay a debt or that the consumer wishes the debt collector to cease further communication with the consumer, the debt collector shall not communicate further with the consumer with respect to such debt, except—"],[1,"(1) to advise the consumer that the debt collector's further efforts are being terminated;"],[1,"(2) to notify the consumer that the debt collector or creditor may invoke specified remedies which are ordinarily invoked by such debt collector or creditor; or"],[1,"(3) where applicable, to notify the consumer that the debt collector or creditor intends to invoke a specified remedy."],[0,"If such notice from the consumer is made by mail, notification shall be complete upon receipt."],[0,"(d) \"Consumer\" defined"],[0,"For the purpose of this section, the term \"consumer\" includes the consumer's spouse, parent (if the consumer is a minor), guardian, executor, or administrator."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692c. Communication in connection with debt collection","tname":"Commerce and Trade","by":{"0":"20","1":"3, 47, 44, 34, 43, 47","2":"17, 17, 17, 17","3":"20"}},{"t":"usc","label":"15 U.S.C. § 1692d","url":"https://www.law.cornell.edu/uscode/text/15/1692d","subs":["(1)","(2)"],"stext":{"head":"§1692d. Harassment or abuse","paras":[[0,"A debt collector may not engage in any conduct the natural consequence of which is to harass, oppress, or abuse any person in connection with the collection of a debt. Without limiting the general application of the foregoing, the following conduct is a violation of this section:"],[1,"(1) The use or threat of use of violence or other criminal means to harm the physical person, reputation, or property of any person."],[1,"(2) The use of obscene or profane language or language the natural consequence of which is to abuse the hearer or reader."],[1,"(3) The publication of a list of consumers who allegedly refuse to pay debts, except to a consumer reporting agency or to persons meeting the requirements of section 1681a(f) or 1681b(3) 1 of this title."],[1,"(4) The advertisement for sale of any debt to coerce payment of the debt."],[1,"(5) Causing a telephone to ring or engaging any person in telephone conversation repeatedly or continuously with intent to annoy, abuse, or harass any person at the called number."],[1,"(6) Except as provided in section 1692b of this title, the placement of telephone calls without meaningful disclosure of the caller's identity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692d. Harassment or abuse","tname":"Commerce and Trade","by":{"0":"4, 4","1":"34","2":"17"}},{"t":"usc","label":"15 U.S.C. § 1692e","url":"https://www.law.cornell.edu/uscode/text/15/1692e","subs":["(10)","(2)","(11)"],"stext":{"head":"§1692e. False or misleading representations","paras":[[0,"A debt collector may not use any false, deceptive, or misleading representation or means in connection with the collection of any debt. Without limiting the general application of the foregoing, the following conduct is a violation of this section:"],[1,"(1) The false representation or implication that the debt collector is vouched for, bonded by, or affiliated with the United States or any State, including the use of any badge, uniform, or facsimile thereof."],[1,"(2) The false representation of—"],[2,"(A) the character, amount, or legal status of any debt; or"],[2,"(B) any services rendered or compensation which may be lawfully received by any debt collector for the collection of a debt."],[1,"(3) The false representation or implication that any individual is an attorney or that any communication is from an attorney."],[1,"(4) The representation or implication that nonpayment of any debt will result in the arrest or imprisonment of any person or the seizure, garnishment, attachment, or sale of any property or wages of any person unless such action is lawful and the debt collector or creditor intends to take such action."],[1,"(5) The threat to take any action that cannot legally be taken or that is not intended to be taken."],[1,"(6) The false representation or implication that a sale, referral, or other transfer of any interest in a debt shall cause the consumer to—"],[2,"(A) lose any claim or defense to payment of the debt; or"],[2,"(B) become subject to any practice prohibited by this subchapter."],[1,"(7) The false representation or implication that the consumer committed any crime or other conduct in order to disgrace the consumer."],[1,"(8) Communicating or threatening to communicate to any person credit information which is known or which should be known to be false, including the failure to communicate that a disputed debt is disputed."],[1,"(9) The use or distribution of any written communication which simulates or is falsely represented to be a document authorized, issued, or approved by any court, official, or agency of the United States or any State, or which creates a false impression as to its source, authorization, or approval."],[1,"(10) The use of any false representation or deceptive means to collect or attempt to collect any debt or to obtain information concerning a consumer."],[1,"(11) The failure to disclose in the initial written communication with the consumer and, in addition, if the initial communication with the consumer is oral, in that initial oral communication, that the debt collector is attempting to collect a debt and that any information obtained will be used for that purpose, and the failure to disclose in subsequent communications that the communication is from a debt collector, except that this paragraph shall not apply to a formal pleading made in connection with a legal action."],[1,"(12) The false representation or implication that accounts have been turned over to innocent purchasers for value."],[1,"(13) The false representation or implication that documents are legal process."],[1,"(14) The use of any business, company, or organization name other than the true name of the debt collector's business, company, or organization."],[1,"(15) The false representation or implication that documents are not legal process forms or do not require action by the consumer."],[1,"(16) The false representation or implication that a debt collector operates or is employed by a consumer reporting agency as defined by section 1681a(f) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692e. False or misleading representations","tname":"Commerce and Trade","by":{"0":"4, 4","1":"3, 30, 44, 47","2":"17","3":"4, 21, 5, 17"}},{"t":"usc","label":"15 U.S.C. § 1692f","url":"https://www.law.cornell.edu/uscode/text/15/1692f","subs":["(1)","(6)","(2)","(3)","(4)","(5)","(7)","(8)","(6)(A)","(6)(B)","(6)(C)"],"stext":{"head":"§1692f. Unfair practices","paras":[[0,"A debt collector may not use unfair or unconscionable means to collect or attempt to collect any debt. Without limiting the general application of the foregoing, the following conduct is a violation of this section:"],[1,"(1) The collection of any amount (including any interest, fee, charge, or expense incidental to the principal obligation) unless such amount is expressly authorized by the agreement creating the debt or permitted by law."],[1,"(2) The acceptance by a debt collector from any person of a check or other payment instrument postdated by more than five days unless such person is notified in writing of the debt collector's intent to deposit such check or instrument not more than ten nor less than three business days prior to such deposit."],[1,"(3) The solicitation by a debt collector of any postdated check or other postdated payment instrument for the purpose of threatening or instituting criminal prosecution."],[1,"(4) Depositing or threatening to deposit any postdated check or other postdated payment instrument prior to the date on such check or instrument."],[1,"(5) Causing charges to be made to any person for communications by concealment of the true purpose of the communication. Such charges include, but are not limited to, collect telephone calls and telegram fees."],[1,"(6) Taking or threatening to take any nonjudicial action to effect dispossession or disablement of property if—"],[2,"(A) there is no present right to possession of the property claimed as collateral through an enforceable security interest;"],[2,"(B) there is no present intention to take possession of the property; or"],[2,"(C) the property is exempt by law from such dispossession or disablement."],[1,"(7) Communicating with a consumer regarding a debt by post card."],[1,"(8) Using any language or symbol, other than the debt collector's address, on any envelope when communicating with a consumer by use of the mails or by telegram, except that a debt collector may use his business name if such name does not indicate that he is in the debt collection business."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692f?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1692f. Unfair practices","tname":"Commerce and Trade","by":{"0":"4, passim","1":"3, 22, 22, 22, 22, 22, passim, 22, 34, 22","2":"17, 17, 17, 17, 1","3":"5, 17, passim"}},{"t":"usc","label":"15 U.S.C. § 1692g","url":"https://www.law.cornell.edu/uscode/text/15/1692g","subs":["(a)","(b)","(a)(3)","(d)","(e)"],"stext":{"head":"§1692g. Validation of debts","paras":[[0,"(a) Notice of debt; contents"],[0,"Within five days after the initial communication with a consumer in connection with the collection of any debt, a debt collector shall, unless the following information is contained in the initial communication or the consumer has paid the debt, send the consumer a written notice containing—"],[1,"(1) the amount of the debt;"],[1,"(2) the name of the creditor to whom the debt is owed;"],[1,"(3) a statement that unless the consumer, within thirty days after receipt of the notice, disputes the validity of the debt, or any portion thereof, the debt will be assumed to be valid by the debt collector;"],[1,"(4) a statement that if the consumer notifies the debt collector in writing within the thirty-day period that the debt, or any portion thereof, is disputed, the debt collector will obtain verification of the debt or a copy of a judgment against the consumer and a copy of such verification or judgment will be mailed to the consumer by the debt collector; and"],[1,"(5) a statement that, upon the consumer's written request within the thirty-day period, the debt collector will provide the consumer with the name and address of the original creditor, if different from the current creditor."],[0,"(b) Disputed debts"],[0,"If the consumer notifies the debt collector in writing within the thirty-day period described in subsection (a) that the debt, or any portion thereof, is disputed, or that the consumer requests the name and address of the original creditor, the debt collector shall cease collection of the debt, or any disputed portion thereof, until the debt collector obtains verification of the debt or a copy of a judgment, or the name and address of the original creditor, and a copy of such verification or judgment, or name and address of the original creditor, is mailed to the consumer by the debt collector. Collection activities and communications that do not otherwise violate this subchapter may continue during the 30-day period referred to in subsection (a) unless the consumer has notified the debt collector in writing that the debt, or any portion of the debt, is disputed or that the consumer requests the name and address of the original creditor. Any collection activities and communication during the 30-day period may not overshadow or be inconsistent with the disclosure of the consumer's right to dispute the debt or request the name and address of the original creditor."],[0,"(c) Admission of liability"],[0,"The failure of a consumer to dispute the validity of a debt under this section may not be construed by any court as an admission of liability by the consumer."],[0,"(d) Legal pleadings"],[0,"A communication in the form of a formal pleading in a civil action shall not be treated as an initial communication for purposes of subsection (a)."],[0,"(e) Notice provisions"],[0,"The sending or delivery of any form or notice which does not relate to the collection of a debt and is expressly required by title 26, title V of Gramm-Leach-Bliley Act [15 U.S.C. 6801 et seq.], or any provision of Federal or State law relating to notice of data security breach or privacy, or any regulation prescribed under any such provision of law, shall not be treated as an initial communication in connection with debt collection for purposes of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692g?type=usc&year=mostrecent&link-type=html"},"head":"§1692g. Validation of debts","tname":"Commerce and Trade","by":{"0":"4, 7, 8, 7, 7","1":"9, 24, 16, 45, passim, 47","2":"1, 1","3":"17, 21, 4, 21, 3"}},{"t":"usc","label":"15 U.S.C. § 1692i","url":"https://www.law.cornell.edu/uscode/text/15/1692i","subs":["(a)(1)","(a)","(a)(2)"],"stext":{"head":"§1692i. Legal actions by debt collectors","paras":[[0,"(a) Venue"],[0,"Any debt collector who brings any legal action on a debt against any consumer shall—"],[1,"(1) in the case of an action to enforce an interest in real property securing the consumer's obligation, bring such action only in a judicial district or similar legal entity in which such real property is located; or"],[1,"(2) in the case of an action not described in paragraph (1), bring such action only in the judicial district or similar legal entity—"],[2,"(A) in which such consumer signed the contract sued upon; or"],[2,"(B) in which such consumer resides at the commencement of the action."],[0,"(b) Authorization of actions"],[0,"Nothing in this subchapter shall be construed to authorize the bringing of legal actions by debt collectors."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692i?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692i. Legal actions by debt collectors","tname":"Commerce and Trade","by":{"0":"10, 3, 10, 21, 26","1":"38, 37, 38","2":"1, 1","3":"passim, 16"}},{"t":"usc","label":"15 U.S.C. § 1692n","url":"https://www.law.cornell.edu/uscode/text/15/1692n","stext":{"head":"§1692n. Relation to State laws","paras":[[0,"This subchapter does not annul, alter, or affect, or exempt any person subject to the provisions of this subchapter from complying with the laws of any State with respect to debt collection practices, except to the extent that those laws are inconsistent with any provision of this subchapter, and then only to the extent of the inconsistency. For purposes of this section, a State law is not inconsistent with this subchapter if the protection such law affords any consumer is greater than the protection provided by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692n?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692n. Relation to State laws","tname":"Commerce and Trade","by":{"0":"28","1":"42","2":"20","3":"20"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"1","1":"1"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Bank of America v. Kosovich","cite":"878 P.2d 65","y":1994,"court":"Colo. App.","url":"https://www.courtlistener.com/c/P.2d/878/65/","op":1,"by":{"1":"7","2":"8"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"BFP v. Resolution Trust Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"1":"passim","2":"5","3":"19"}},{"t":"case","label":"(III) Cases—continued: Birster v. American Home Mortgage Servicing, Inc.","cite":"481 Fed. Appx. 579","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./481/579/","by":{"1":"28"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Community for Creative Non-Violence v. Reid","cite":"490 U.S. 730","y":1989,"id":"1988/88-293","sc":1,"sum":"The Court held that the statue's preparation was not a \"work for hire\" as defined by the Act because Reid was not a CCNV employee. Instead, CCNV hired Reid as an independent contractor.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Dewsnup v. Timm","cite":"502 U.S. 410","y":1992,"id":"1991/90-741","sc":1,"sum":"Section 506(d) does not allow Dewsnup to \"strip down\" respondents' lien to the judicially determined value of the collateral, because respondents' claim is secured by a lien and has been fully allowed pursuant to § 502 and, therefore, cannot be classified as \"not an allowed secured claim\" for purposes of the lien-voiding provision of § 506(d).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Federal Home Loan Mortgage Corp. v. Lamar","cite":"503 F.3d 504","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/503/504/","by":{"1":"49"}},{"t":"case","label":"Folda Real Estate Co. v. Jacobsen","cite":"223 Pac. 748","y":1924,"court":"Colo.","url":"https://www.courtlistener.com/c/Pac./223/748/","by":{"1":"5"}},{"t":"case","label":"Foothills Holding Corp. v. Tulsa Rig, Reel & Manufacturing Co.","cite":"393 P.2d 749","y":1964,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/393/749/","by":{"1":"5"}},{"t":"case","label":"Freeman v. Alderson","cite":"119 U.S. 185","y":1886,"id":"scdb/1886-032","sc":1,"sum":"A personal judgment for costs may not be rendered against tbe defendant, on default, in an action of trespass to try title to real estate, if citation was served on liim by publication, as anon-resident, and not personally and if such judgment be entered, it cannot be enforced against other property of the defendant within the jurisdiction of the court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Grden v. Leikin Ingber & Winters PC","cite":"643 F.3d 169","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/643/169/","by":{"1":"30, 31, 34"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Johnson v. Home State Bank","cite":"501 U.S. 78","y":1991,"id":"1990/90-693","sc":1,"sum":"After petitioner Johnson defaulted on promissory notes secured with a mortgage on his farm, respondent Home State Bank (Bank) began foreclosure proceedings in state court. While foreclosure proceedings were pending, Johnson filed for liquidation under Chapter 7 of the Bankruptcy Code, and the Bankruptcy Court discharged him from personal liability on the notes. However, because the Bank's right to proceed against …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21","3":"14"}},{"t":"case","label":"Kirchner v. Sanchez","cite":"661 P.2d 1161","y":1983,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/661/1161/","by":{"1":"27"}},{"t":"case","label":"Land Title Insurance Corp. v. Ameriquest Mortgage Co.","cite":"207 P.3d 141","y":2009,"court":"Colo.","url":"https://www.courtlistener.com/c/P.3d/207/141/","by":{"1":"6"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"1":"20, 36"}},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Ozmun v. Reynolds","cite":"11 Minn. 459","y":1866,"url":"https://www.courtlistener.com/c/Minn./11/459/","by":{"1":"21"}},{"t":"case","label":"Plymouth Capital Co. v. District Court","cite":"955 P.2d 1014","y":1998,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/955/1014/","by":{"1":"5, 6"}},{"t":"case","label":"Rice v. Santa Fe Elevator Corp.","cite":"331 U.S. 218","y":1947,"id":"scdb/1946-098","sc":1,"sum":"1. By the 1931 amendments to §§ 6 and 29 of the United States Warehouse Act, Congress terminated the dual system of regulation provided by the original Act and substituted an exclusive system of federal regulation of warehouses licensed under the Federal Act with reference to the subjects covered thereby, except to the extent that express exceptions in the Federal Act subject certain phases of the business to state …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Roberts v. Sea-Land Services","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"1":"19, 20","2":"15"}},{"t":"case","label":"Romine v. Diversified Collection Services, Inc.","cite":"155 F.3d 1142","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/155/1142/","by":{"1":"32"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36","2":"29"}},{"t":"case","label":"Schlaf v. Safeguard Property, LLC","cite":"899 F.3d 459","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/899/459/","by":{"1":"31, 32"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Sheriff v. Gillie","cite":"136 S. Ct. 1594","y":2016,"id":"2015/15-338","sc":1,"sum":"The Court held that, regardless of whether special counsel appointed by the Attorney General to collect debts are “state officers” under the Federal Debt Collection Practices Act, the use of Attorney General letterhead by such special counsel is not materially misleading.","sumSrc":"Oyez","by":{"1":"42","3":"20"}},{"t":"case","label":"Siwulec v. J.M. Adjustment Services, LLC","cite":"465 Fed. Appx. 200","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./465/200/","by":{"1":"32"}},{"t":"case","label":"Sumers v. Board of Commissioners of Garfield County","cite":"184 P.2d 144","y":1947,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/184/144/","by":{"1":"21"}},{"t":"case","label":"United States v. Brosnan","cite":"363 U.S. 237","y":1960,"id":"1959/137","sc":1,"sum":"Under Pennsylvania law, the sheriff's sale under a writ of fierifacias was a judicial sale; but the doctrine of sovereign immunity from unconsented suits has not yet been","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41, 42"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"sum":"The Court held that the fiduciary exception to the attorney-client privilege does not apply to the general trust relationship between the United States and the Indian Tribes.","sumSrc":"Oyez","by":{"1":"19, 20"}},{"t":"case","label":"Woodson v. Murdock","cite":"89 U.S. 351","y":1874,"id":"scdb/1874-016","sc":1,"sum":"1. The provision of the constitution of Missouri, which ordains—","sumSrc":"Headnote (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(51)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Bankruptcy","by":{"1":"8, 21, 40, 46","2":"20"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"23"}},{"t":"usc","label":"15 U.S.C. § 1692h","url":"https://www.law.cornell.edu/uscode/text/15/1692h","by":{"1":"3"}},{"t":"usc","label":"15 U.S.C. § 1692k","url":"https://www.law.cornell.edu/uscode/text/15/1692k","by":{"1":"3"}},{"t":"usc","label":"15 U.S.C. § 1692o","url":"https://www.law.cornell.edu/uscode/text/15/1692o","by":{"1":"46, 47"}},{"t":"usc","label":"28 U.S.C. § 3001","url":"https://www.law.cornell.edu/uscode/text/28/3001","by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 3003","url":"https://www.law.cornell.edu/uscode/text/28/3003","subs":["(b)"],"by":{"1":"22"}},{"t":"usc","label":"12 U.S.C. § 3701","url":"https://www.law.cornell.edu/uscode/text/12/3701","by":{"1":"22"}},{"t":"usc","label":"12 U.S.C. § 3705","url":"https://www.law.cornell.edu/uscode/text/12/3705","by":{"1":"22"}},{"t":"usc","label":"12 U.S.C. § 3751","url":"https://www.law.cornell.edu/uscode/text/12/3751","by":{"1":"22"}},{"t":"usc","label":"12 U.S.C. § 3755","url":"https://www.law.cornell.edu/uscode/text/12/3755","subs":["(b)(1)"],"by":{"1":"22"}},{"t":"usc","label":"12 U.S.C. § 3768","url":"https://www.law.cornell.edu/uscode/text/12/3768","subs":["(a)(1)"],"by":{"1":"22"}},{"t":"usc","label":"37 U.S.C. § 305a","url":"https://www.law.cornell.edu/uscode/text/37/305a","subs":["(e)(1)(B)","(e)(3)"],"by":{"1":"18, 18"}},{"t":"usc","label":"38 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/38/101","subs":["(2)"],"by":{"1":"18"}},{"t":"usc","label":"38 U.S.C. § 3701","url":"https://www.law.cornell.edu/uscode/text/38/3701","subs":["(b)(3)","(b)(6)"],"by":{"1":"18, 18"}},{"t":"reg","label":"12 C.F.R. § 1006.4","url":"https://www.ecfr.gov/current/title-12/section-1006.4","subs":["(a)(1)"],"by":{"1":"47, 47"}},{"t":"reg","label":"12 C.F.R. § 1090.105","url":"https://www.ecfr.gov/current/title-12/section-1090.105","subs":["(a)"],"by":{"1":"23"}},{"t":"reg","label":"53 Fed. Reg. 50,097","url":"https://www.govinfo.gov/link/fr/53/50097","by":{"1":"23","2":"15","3":"14"}},{"t":"reg","label":"60 Fed. Reg. 66,972","url":"https://www.govinfo.gov/link/fr/60/66972","by":{"1":"47"}},{"t":"reg","label":"77 Fed. Reg. 65,775","url":"https://www.govinfo.gov/link/fr/77/65775","by":{"1":"23"}},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"sum":"Apart from certain special provisions, the Bankruptcy Act generally leaves the determination of property rights in the assets of a bankrupt's estate to BUTNER v. UNITED STATES","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Clark v. Rameker","cite":"134 S. Ct. 2242","y":2014,"id":"2013/13-299","sc":1,"sum":"The Court held that the U.S. Bankruptcy Code does not exempt inherited retirement accounts from a debtor's estate in bankruptcy proceedings.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"(III) Cases—Continued: McNair v. Maxwell & Morgan PC","cite":"893 F.3d 680","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/893/680/","by":{"2":"25"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"2":"28, 29"}},{"t":"usc","label":"15 U.S.C. § 1692c-1692g","url":"https://www.law.cornell.edu/uscode/text/15/1692c-1692g","by":{"2":"2"}},{"t":"usc","label":"15 U.S.C. § 1692c-1692h","url":"https://www.law.cornell.edu/uscode/text/15/1692c-1692h","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 1692l","url":"https://www.law.cornell.edu/uscode/text/15/1692l","subs":["(a)","(d)"],"by":{"2":"1, 20"}},{"t":"usc","label":"7 U.S.C. § 1631","url":"https://www.law.cornell.edu/uscode/text/7/1631","subs":["(c)(7)"],"by":{"2":"20"}},{"t":"usc","label":"11 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/11/1110","subs":["(d)(2)"],"by":{"2":"20"}},{"t":"usc","label":"11 U.S.C. § 1168","url":"https://www.law.cornell.edu/uscode/text/11/1168","subs":["(d)(2)"],"by":{"2":"20"}},{"t":"usc","label":"26 U.S.C. § 6323","url":"https://www.law.cornell.edu/uscode/text/26/6323","subs":["(h)(1)"],"by":{"2":"20"}},{"t":"usc","label":"49 U.S.C. § 14301","url":"https://www.law.cornell.edu/uscode/text/49/14301","subs":["(a)(3)"],"by":{"2":"20"}},{"t":"case","label":"James v. Ford Motor Credit Co.","cite":"47 F.3d 961","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/47/961/","by":{"3":"12"}},{"t":"case","label":"Mount Lemmon Fire Dist. v. Guido","cite":"139 S. Ct. 22","y":2018,"id":"2018/17-587","sc":1,"sum":"State and local governments are covered employers under the Age Discrimination in Employment Act of 1967 regardless of the number of employees they have.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"10, 20"}},{"t":"usc","label":"15 U.S.C. § 1692m","url":"https://www.law.cornell.edu/uscode/text/15/1692m","subs":["(a)"],"by":{"3":"15"}}]};